  "name": "喷油（喷漆）",
  "lv": 1,
  "img": "images/core18.jpg",
  "points": "溶剂型/UV型涂料；遮盖基材瑕疵、做色彩质感；需控制膜厚与附着力。底漆加面漆总膜厚约 20–60μm，耐候靠清漆或 UV 面漆；附着力由前处理（脱脂除尘）决定，不是由油漆品牌决定。",
  "usage": "灯具外观件常规工艺；注意儿童用品需无毒涂料。喷涂前必须脱脂除尘，单次喷涂厚度有限，通常两道以上。",
