  "points": "高压高速充型必然裹气，气孔是压铸件固有特征（约占体积 0.1–1%）；厚大截面补缩不足形成缩孔缩松。规避靠控壁厚、避免热节、排气槽与工艺参数，而不是靠事后挽救。",
