  "lv": 1,
  "points": "等截面连续挤出，截面各部分金属流速必须一致；壁厚差过大时薄处流速快、厚处慢，型材扭拧弯曲。设计原则：全截面壁厚接近（6063 推荐 1.0–3.0mm），对称布置，避免尖角与实心厚块。",
  "usage": "画型材截面先把功能槽（灯槽/卡槽/走线槽）对称布置；厚位用空腔减薄；散热鳍片根部加 R，鳍厚 ≥ 1.0mm、高厚比 ≤ 8:1。",
