  "points": "一次挤出可集成：PC LED 板卡槽、扩散罩卡口、端盖止口、走线槽、T 型/燕尾安装槽、散热鳍片、定位键。这是型材工艺最大的结构红利——装配特征「长」在截面上，零装配成本。",
  "usage": "灯具型材把电气仓、光学仓、散热器合三为一；截面预留 0.5–1.0mm 单边弹性变形量做卡装（PC 罩压入式装配）；端面配合公差 ±0.1 由切剖加工保证。",
