  "points": "扭拧/弯曲/波浪来自截面流速不均（模具分流孔设计问题）或淬火冷却不均；粗晶环来自表皮再结晶（挤压比低、温度高），阳极氧化后呈粗大晶粒斑。规避：截面均衡设计+模具氮化试模修正，氧化前控制挤压工艺。",
  "usage": "图纸标注扭拧 ≤ 1°/m、弯曲 ≤ 0.5mm/m（精细级）；外观件指定「氧化前粗晶检验」；卡槽配合面避开粗晶高风险的表层。",
