  "name": "钣金折弯的回弹控制",
  "lv": 1,
  "img": "images/plus59.jpg",
  "imgKw": "sheet metal bending springback compensation",
  "points": "折弯卸载后角度「弹回」，本质是塑性变形区残留弹性应变；回弹量与 R/t 成正比、与材料屈服强度正相关，R/t>5 显著增大。经验值：软钢 1–2°、铝 2–3°、不锈钢 3–5°（90° 折弯）；窄长件折弯后易翘曲扭曲。控制三类：补偿（过弯 / 数控补偿角）、约束（压料 / 校形）、改结构（减小 R/t、加筋翻边）。",
  "usage": "所有 90° 折弯件首件必实测回弹角，换料（尤其换不锈钢 / 高强钢）必须重新标定补偿；窄长件对称布置两条折弯线、先内后外折弯防翘曲；允许的折弯角度公差按 GB/T 13915 取值，超差调刀补正并记录「材料-角度」对照表。",
  "imgAi": "工程示意图：钣金折弯回弹。线条简洁、轴侧视角、白底，标注折弯半径 R、板厚 t、回弹前后角度差，无人物场景，工程师参考图风格。",
