  "points": "抽芯铆钉可单面操作、效率高但不可拆；实心铆强度高、需双面操作；铆接孔径一般比钉径大 0.1–0.2mm，铆接顺序影响整体变形。",
  "usage": "钣金件之间的固定连接。需要拆卸的部位不要用铆接，改用螺钉或压铆螺母；薄板铆接要避免钉头压陷。",
