  "name": "去应力退火",
  "lv": 1,
  "points": "焊接、机加、冲压后内部存在残余应力，放置或后续加工会缓慢变形；去应力退火（钢约 550–650℃、铝约 200–300℃）能显著降低变形量。",
  "usage": "焊接框架、大平面机加件、精密钣金件。工序安排在粗加工之后、精加工与表面处理之前，否则精加工尺寸会被后续变形吃掉。",
