  "points": "顺序原则：先成形后热处理，先热处理后精加工，先机加后表面处理，压铆与铆接在喷涂之前，螺纹类在热处理之后、喷涂之前完成并遮蔽。",
  "usage": "排工艺卡时用这张顺序逐项核对：成形 → 热处理 → 机加与攻丝 → 压铆/铆接 → 表面处理 → 丝印 → 装配。顺序颠倒往往直接造成批量返工。",
