  "lv": 1,
  "points": "最常见的翻车点：手板是 CNC / 打印件，量产是注塑件 —— 缩水、脱模斜度、壁厚差异会让装配关系变样；打印件各向异性，卡扣弹性与注塑件完全不同。",
  "usage": "手板验证装配前先对齐「材料 + 成型方式」；卡扣类必须用同材料注塑小样或按注塑件校核，别拿打印件当最终结论。",
