  "name": "打样交期与成本结构",
  "lv": 1,
  "points": "计价方式各不相同：3D 打印按克或按件、CNC 按工时、复模按模具加件数、快模按模具加试模；交期通常 3D 打印 2–3 天、CNC 3–5 天、复模 5–7 天。",
  "usage": "排计划时给「手板 → 修改 → 再手板」留两轮；第二轮只做有问题的零件，不做整套，省时间也省成本。",
