  "points": "车件的精度与粗糙度按配合要求给：轴承位通常 Ra0.8 以内、公差 g6 / h7；没有装配关系的自由尺寸不要给严公差，成本会陡增。",
  "usage": "导向轴、衬套、销钉；图纸按「配合面 / 自由面」分级标注公差与粗糙度，减少不必要的精加工。",
