  "points": "压制适合浅而规整的罩与面板（尺寸准、成本低、壁厚均匀）；吹制适合深腔与球泡形（壁厚不易均匀）；离心成型用于圆形大罩。壁厚均匀性：压制优于吹制。",
  "usage": "按「形状深度 + 壁厚要求 + 批量」选成型方式；深腔件要在图纸上标注允许的壁厚偏差（常见 ±20–30%）。",
