  "name": "PE（聚乙烯）",
  "lv": 2,
  "points": "最轻的通用塑料之一，密度 0.91–0.95 g/cm³；半透明白蜡状、结晶性，屈服能力高但不易回复；耐水与耐化学药品性好、介电性能优、透水率低；使用温度约 80–100℃，机械强度不高、质软，成型收缩大（1.5–4.0%），表面不易粘接与印刷。HDPE 刚硬，LDPE 柔韧。",
  "usage": "胶袋、水桶、电线包皮、玩具、建材；结构上适合做低摩擦耐磨件（导轨、滑套）与耐腐蚀件，不适合承力结构件和需要印刷、粘接的外观面。",
