  "name": "塑料回收标识（三角标 1–7）",
  "lv": 2,
  "points": "塑料制品底部的三角标用 1–7 表示材料类别：1 PET、2 HDPE、3 PVC、4 LDPE、5 PP、6 PS、7 其他类塑料；现行依据是 GB/T 16288-2024（代替 1998、2008 两版）。编号 7 只表示「其他」，并不专指 PC——PC、ABS、PMMA、PA、PC/ABS 都归在 7。食品接触用途另受 GB 4806 系列约束，PC 婴幼儿奶瓶已被明令禁止。",
  "usage": "选材评审、食品接触件判定、出口件的材质声明与回收要求；设计时预留标识位置并按 GB/T 16288 标注材质，不要凭「7 号是 PC」这类流传说法判断材料。",
  "imgKw": "塑料回收标识 三角标 1-7 PET HDPE PP",
