  "name": "六角孔配圆 Pin（紧钉定位）",
  "lv": 3,
  "points": "外形拆件后组装常出现外形不相配，需要做准数的定位柱来配合外形。外观上的定位一般用六角孔紧配圆形塑料柱：因为是紧配，六角孔与圆柱之间不需要虚位、也不做脱模角，但六角孔和胶柱顶端都必须加导入角。六角孔配圆柱也常用作胶水柱装配，此时要用加大的尺寸 x′ 给两者留出藏胶水的空间。",
  "usage": "外观拆件的定位；胶水粘接结构的藏胶空间设计。",
  "imgKw": "六角孔 圆Pin 紧钉 定位柱 胶水柱 导入角",
