  "points": "电池门与壳身常用机牙螺丝配藏在壳身的六角丝帽收紧。在壳身内按六角丝帽尺寸做出六角孔套筒，并给单边 0.15mm 虚位（方便放入），再用热熔或冷打的方法把丝帽固定住不使其跌出。",
