  "name": "底刮与面刮（段差控制）",
  "lv": 2,
  "points": "上下壳理论外形可以重合，但受模具制造精度与注塑参数影响，实际尺寸不会一致——面壳大于底壳叫「面刮」，底壳大于面壳叫「底刮」。可接受面刮 <0.15mm，可接受底刮 <0.1mm。所以在无法保证零段差（截面图中底面壳的尺寸落差）时，设计上应尽量做到面壳 > 底壳。",
  "usage": "上下壳（前后壳）配合段的段差设计取向；外观件配合线验收标准的制定。",
  "imgKw": "面刮 底刮 段差 上下壳 配合线 外观",
