  "name": "支承面设计（凸点 / 凸环）",
  "lv": 3,
  "points": "塑胶易变形，在定位上应当归为毛坯的定位一类——定位面积要小。平面的支承应改为小凸点或凸环，例如遥控器底部一般设三个或四个凸点作为支承面。理由是大平面本身不平，用大面积支承等于把不平度直接传成晃动。",
  "usage": "整机底面支承、内部件的承托面、需要稳定放置或定位的结构。",
