  "name": "旋钮与推钮设计",
  "lv": 2,
  "points": "旋钮一般装在可变电阻（音量钮）和可变电容（调台钮）上，要求不能直接看到产品内部结构，所以钮的形状要加相应骨位；旋钮侧面一般做防滑结构或装饰纹。推钮一般装在滑动开关上：与开关柄装配单边间隙取 1.0mm；钮孔大小 = 行程 + 钮的外形尺寸 + 双边间隙（一般 2.0mm）；推钮高度要符合人机工程，一般高出装配面 1.0–3.0mm；推钮要做裙边以避免看到内部结构。",
  "usage": "音量/调台旋钮、电源与功能推钮的结构设计；涉及手感、行程与遮挡的三项校核。",
  "imgKw": "旋钮 推钮 滑动开关 裙边 行程 防滑纹",
