  "name": "橡胶按键（导电胶）设计",
  "lv": 3,
  "points": "橡胶钮一般是压制模做出来的，因橡胶弹性及伸缩率较高，外形一般不拔模，多用于遥控器和手机。按钮柱子底部与电路板的行程间隙为 1.0mm；柱子底部植碳（丝印石墨类导电层）；钮与外形零件的单边间隙 0.3–0.5mm（手机为 0.15mm）；不同按键间要压紧以免按压时连动。定位上一般 x/y 方向用定位柱，单边间隙 0.05mm，z 轴方向直接用电路板和胶件压紧。",
  "usage": "遥控器、手机、仪表的整片式按键；需要良好手感、密封性或低成本多键位的场合。",
