  "name": "PCB 与塑胶件的装配方式",
  "lv": 2,
  "points": "按电路板与塑胶件开模方向的关系分三种装配方式：垂直时，用两个螺丝柱同时兼作定位柱（最常见）；平行时，用两个螺丝柱兼限位骨定位，两个螺丝带介子或喇叭码压紧电路板；成一定夹角时，按键板先装在塑胶支架上再装到壳体，或把螺丝柱切成相应角度并另加辅助胶件来打螺丝（否则螺丝易歪斜）。夹角方案不常用，但外形与排版受限时效果很好。",
  "usage": "所有含 PCB 的机型的固定方案设计；判断该用哪种固定方式、以及要不要为 PCB 加辅助支架。",
