  "name": "压延成型",
  "lv": 3,
  "points": "压延是把树脂与各种添加剂经预期处理（捏合、过滤等）后，通过压延机两个或多个转向相反的压延辊的间隙加工成薄膜或片材，随后从辊筒上剥离、再经冷却定型。它主要用于聚氯乙烯，能制造薄膜、片材、板材、人造革、地板砖等制品。",
  "usage": "PVC 薄膜、片材、人造革、地板砖的连续生产；判断「片材类塑胶件」该用压延还是挤出。",
