  "name": "轴承选型与寿命计算",
  "lv": 1,
  "points": "选轴承先算寿命：L10 = (C/P)^p × 10⁶ 转（球轴承 p = 3、滚子轴承 p = 10/3），换成小时 L10h = 10⁶/(60n) × (C/P)^p；当量动载荷 P = X·Fr + Y·Fa，还要乘载荷系数 fp（平稳 1.0–1.2、强烈冲击 1.8–3.0）。低速或摆动工况按额定静载荷校核 C0/P0 ≥ 2–3。选型顺序：按受力方向定类型（径向 → 深沟球；径向 + 轴向 → 角接触 / 圆锥滚子；纯轴向 → 推力）→ 按寿命定尺寸 → 按转速、温度与游隙校核润滑。",
  "usage": "所有旋转轴系的支撑：电动工具、洗衣机、汽车轮毂与电机、自动化设备、医疗设备。塑料壳体里直接压轴承外圈是经典错误——塑料蠕变后外圈松动、跑圈、磨出粉，必须用金属嵌件或加大配合面并做轴向止动。",
  "imgKw": "滚动轴承 选型 寿命 L10 当量动载荷 配合 游隙",
  "imgAi": "工程示意图：轴承选型流程与 L10 寿命计算要素。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
  "std": [
   "GB/T 6391-2010",
   "ISO 281:2007",
   "GB/T 4662-2025",
   "GB/T 275-2015",
   "GB/T 307.1-2017"
  ]
