  "name": "联轴器选型",
  "lv": 3,
  "points": "联轴器选型就是四件事：扭矩够不够（T = 9550·P/n 再乘工况系数 1.3–3，伺服要按启动瞬时扭矩 2–3 倍算）、能不能补偿偏差（径向 / 角度 / 轴向）、要不要零背隙（伺服定位必须，普通传动可放宽）、惯量能否接受（联轴器惯量最好 ≤ 电机转子惯量的 10%–25%）。刚性联轴器不允许任何偏差，只用于两轴严格对中或本身一体的场合；挠性（梅花 / 膜片 / 波纹管）能吸收偏差但吸收量有上限，装偏了照样把轴承拽坏。",
  "usage": "电机与丝杠、减速器与负载、泵与电机、编码器连接、伺服进给轴。装配必须打表对中（径向 ≤0.03–0.05mm），不能以「弹性联轴器能补偿」为由不做对中。",
  "imgKw": "联轴器 选型 背隙 偏差补偿 膜片 梅花 惯量",
  "imgAi": "工程示意图：常见联轴器类型（梅花 / 膜片 / 波纹管）与偏差补偿。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
