  "name": "直线导轨与滑块",
  "lv": 2,
  "points": "直线导轨的寿命按行程算：L = (C/(fw·P))³ × 50 km（C 为额定动载荷，50 km 是定义额定寿命的基准行程），静载看 C0/P0 ≥ 2–5。精度一大半取决于安装基面：单根导轨安装面直线度、两根导轨平行度都要 ≤0.05mm/1000mm（精密 ≤0.02），并且先靠紧基准侧、再装从动侧。滑块拆下时滚珠脱落、或导轨没装平就通电，都会以「爬行、异响、卡死」的形式暴露出来。",
  "usage": "自动化设备的直线运动轴、CNC 工作台、注塑机与压铸机的移动模板、医疗设备滑台、3D 打印机、升降机构。粉尘与切屑环境必须加刮油板、防护罩或波纹管套，否则滚道等于被当研磨面用。",
  "imgKw": "直线导轨 滑块 预压 平行度 寿命 防尘",
  "imgAi": "工程示意图：直线导轨与滑块的安装基准与平行度要求。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
