  "name": "屈曲与失稳",
  "lv": 3,
  "points": "细长受压件的破坏不是压坏而是「失稳」：欧拉临界载荷 Pcr = π²EI/(μL)²，长度系数 μ 两端铰支取 1.0、两端固支 0.5、一端固支一端自由 2.0、一端固支一端铰支 0.7——同一根杆把约束从铰支改成自由端，承载力只剩 1/4。临界应力写成 σcr = π²E/λ²（λ = μL/i 为长细比，i = √(I/A)），只与 E 和 λ 有关，与材料强度无关。分界：λ ≥ λp（Q235 约 100）为弹性屈曲，欧拉公式有效；λ < λp 用经验公式（Q235 取 σcr = 304 − 1.12λ MPa）；λ < 60 的短粗杆直接按强度算。圆柱壳轴压 σcr ≈ 0.6Et/R，实际因缺陷要打 0.2–0.3 折减；受外压 Pcr = 2E/(1−ν²) × (t/D)³。",
  "usage": "细长撑杆、气缸与液压缸活塞杆、丝杠、薄壁外壳受压、钣金加强筋受压翼缘、纸箱堆码与塑料薄壳长期受载，凡是一压就「弯出去」而不是「压碎」的场合都用它。",
  "imgKw": "屈曲 欧拉临界载荷 长细比 失稳 buckling Euler",
  "imgAi": "工程示意图：欧拉屈曲与不同约束下的计算长度。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
