  "name": "冲击与跌落力学",
  "lv": 2,
  "points": "跌落时能量守恒给出落地速度 v = √(2gh)：1m 对应 4.43 m/s、1.2m 对应 4.85 m/s、1.5m 对应 5.42 m/s、2m 对应 6.26 m/s。动载荷系数是设计的关键：突加载荷约 2 倍、一般冲击 3–5 倍、跌落瞬间可达 10–100 倍，冲击应力 σd = σst × (1 + √(1 + 2h/δst))。产品用脆值 G（能承受的最大加速度，以 g 为单位）表征抗跌能力，经验值：家电 40–60G，消费电子 60–100G，精密仪器 25–40G，机械硬盘工作时 200G 以上。冲击韧性：Q235 室温夏比 V 型 ≥ 27J；塑料悬臂梁缺口冲击 ABS 200–350 J/m、PC 600–900 J/m、PA6-GF30 只有 60–100 J/m（加玻纤强度涨 2–3 倍，冲击强度反降 30–50%）。",
  "usage": "手机与耳机、电动工具、家电、汽车内饰件、医疗手持设备、包装内衬——凡是有「摔」的工况都按它设计；给结构定壁厚、筋位、缓冲垫厚度和外壳转角半径时，第一条判据来自这条。",
