  "name": "有限元分析（FEA）基础",
  "lv": 2,
  "points": "FEA 的流程是「几何简化 → 材料模型 → 边界条件 → 网格 → 求解 → 后处理判读」，六步里最容易被忽视的是最后一步：结果到底可不可信。网格收敛判据是加密一倍后峰值应力变化小于 5%；应力集中处（圆角）至少要 3–5 层单元覆盖、单元尺寸 ≤ R/3；薄壁件（t/L < 0.1）优先用壳单元，用实体则厚度方向至少 3 层单元。材料输入：钢 E = 206GPa / ν = 0.3，铝 69GPa / 0.33，ABS 2.2GPa / 0.35，PC 2.35GPa / 0.37。判读规则：金属看 Von Mises 应力与屈服比、安全系数取 1.3–1.5；塑料看最大主应力且必须用长期（蠕变）模量；尖角、点载荷、全约束边上的应力是奇异点，随网格无限增大，不能采信。",
  "usage": "复杂受力件（机架、支架、承力外壳、连接件）、轻量化设计、跌落与模态分析、失效复盘时用；但先用手算估出量级再用 FEA 细化，才是正确的顺序。",
  "imgKw": "有限元 网格划分 应力云图 FEA mesh convergence",
  "imgAi": "工程示意图：有限元分析流程与网格收敛性检查。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
