  "name": "焊接工艺选型（电弧 / 激光 / 电阻 / 钎焊）",
  "lv": 1,
  "points": "四条判据定工艺：料厚、材料、批量、变形与外观要求。0.5–3mm 薄板大批量首选电阻点焊（节拍秒级、不用填充材料、表面几乎无痕）；1–6mm 结构件用 MIG/MAG，外观件用 TIG（慢但成形好）；0.5–3mm 精密件、热影响区必须小、或要气密的用激光焊；异种材料、热敏件、铜铝过渡用钎焊（母材不熔化）。铝的导热率约是钢的 5 倍且表面有 Al₂O₃ 氧化膜，同厚度焊接功率要比钢高 30–50%，且必须交流 TIG 或双脉冲 MIG 破除氧化膜。",
  "usage": "结构件打样与量产工艺路线的第一道决策，直接影响报价、变形量与后续工序。要注意：气密件优先激光焊或钎焊，电弧焊必须预留补焊与检漏工位；焊缝数量越少越省钱，这是设计端最有效的降本手段。",
  "imgKw": "焊接工艺 对比 MIG TIG laser welding spot welding",
