  "name": "焊缝布置与坡口设计",
  "lv": 2,
  "points": "坡口形式按板厚选：≤3mm 直边 I 形（可不开坡口，留 0–1mm 间隙）；3–8mm 单面 V 形（60°±5°、钝边 0–2mm、根部间隙 0–2mm）；8–20mm 双面 V（X 形）以减半填充量与变形；≥20mm 用 U 形最省填充金属。焊缝布置要避开高应力区、截面突变与加工面：两条平行焊缝间距应 ≥5×板厚且 ≥30mm，焊缝到折弯线距离要 ≥2.5×板厚 + 折弯内半径，到孔边距离 ≥3×板厚。",
  "usage": "出钣金件与结构件图纸时确定坡口与焊缝位置。注意：焊后要机加工或要贴密封面的部位，焊缝必须挪开，否则焊接变形会破坏加工面与密封面；角焊缝优先「双面对称焊」而不是单面加大焊脚。",
  "imgKw": "坡口形式 V形 U形 X形 weld groove 焊缝布置",
