  "name": "焊接质量检验（VT / UT / RT / MT / PT）",
  "lv": 2,
  "points": "五种常规方法各有硬边界：VT 目视（表面成形、咬边、气孔，最便宜，任何探伤之前必做）；PT 渗透（表面开口缺陷，非磁性材料与不锈钢的唯一表面选项）；MT 磁粉（表面与近表面，仅铁磁性材料，灵敏且便宜）；UT 超声（内部缺陷，厚件首选，能给出缺陷深度与自身高度）；RT 射线（内部体积型缺陷，有底片可追溯，但对垂直于射线方向的面型缺陷如裂纹、未熔合可能完全拍不到）。验收等级按 GB/T 19418-2003 / ISO 5817:2023 选 D、C、B（B 最严）；探伤方法与比例必须写进技术要求，不能只写「焊缝按国标验收」。",
  "usage": "写焊接件技术要求、签供应商技术协议时用。经验组合：外观件做 VT + 100% 气密；承力结构件做 VT + UT 抽检；管路环焊缝做 RT；延迟裂纹敏感钢种要焊后 24–48h 才做最终探伤。",
  "imgKw": "焊缝无损检测 超声 射线 磁粉 渗透 NDT weld inspection",
