  "name": "焊接工艺评定与焊工资质",
  "lv": 3,
  "points": "WPS、PQR、WPQ 是单向闭环：先按试件焊接 + 力学与无损试验得到 PQR（证明这么焊行得通），再由 PQR 编制 WPS（现场怎么焊），最后由取得对应资质的焊工按 WPS 执行（WPQ）。PQR 的价值在「覆盖范围」：母材组别、板厚区间、焊接位置、保护气体、极性、热输入范围任一超出都要重新评定。审核看三件事：PQR 的覆盖范围是否覆盖实际产品（尤其板厚与焊接位置）、WPS 是否与 PQR 一致、车间是否真按 WPS 的参数在焊。",
  "usage": "承压件、动载结构、汽车/轨交/医疗供应链的必查项。小批量外观件通常只需焊工持证 + 外观检验；一旦客户需要 PPAP 或第三方审核，三件套就必须闭环，而且评定是绑定供应商的，换厂要重新确认。",
  "imgKw": "焊接工艺评定 WPS PQR 焊工资质 welding procedure qualification",
