  "name": "粘接接头设计（搭接 / 剪切 / 剥离）",
  "lv": 1,
  "points": "胶接最擅长受剪，最怕剥离与劈裂：同一种结构胶的拉剪强度可达 20–30MPa，而剥离强度只有 1–3kN/m 量级，相差一到两个数量级。所以接头优先选搭接、嵌接、套管式（受剪），避免纯对接，更要避免任何让胶层受撕扯的受力方向。搭接长度不是越长越好——应力集中在搭接两端，超过最优长度（常用 12–25mm）的 2–3 倍后承载力不再提升，改为增加搭接宽度更有效。胶层厚度控制在 0.1–0.3mm：太薄（<0.05mm）易缺胶与应力集中，太厚（>0.5mm）内部缺陷增多、剪切强度下降。",
  "usage": "金属、塑料、玻璃、复合材料的装配，减重替代焊接与螺钉，异种材料连接，以及密封与固定一体化的场合。打样阶段先做几片拉剪试片（实际材料 + 实际表面处理）验证破坏模式，再谈量产。",
  "imgKw": "粘接接头 搭接 剪切 剥离 adhesive joint lap shear peel",
  "imgAi": "工程示意图：胶接接头受力形式对比：搭接受剪、对接受拉、剥离与劈裂的受力方向与应力集中部位。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
