  "name": "胶接耐久性与老化",
  "lv": 3,
  "points": "胶接失效多半不是强度不够，而是环境老化：湿热（水分子渗到界面，竞争性取代氢键与化学键，破坏模式由内聚破坏转为界面破坏）、紫外（表层胶粉化，环氧最差、硅酮最好）、温度循环（胶与基材膨胀差产生的剪应力反复加载）、增塑剂迁移（PVC 或软胶中的增塑剂迁移到胶层，软化脱粘）。所以验收要用「老化后强度保持率」而不是初始强度：常见判据是 85℃/85%RH 1000h 或 65℃/95%RH 500h 后保持率 ≥70%（关键件 ≥80%，且仍应为内聚破坏）。长期受载的胶接件还要按蠕变取长期强度，常取短期拉剪强度的 20–35%。",
  "usage": "户外设备、汽车零部件、家电（蒸汽或热水环境）、医疗器械（灭菌）项目必须做。评审时把老化条件、时长、保持率与破坏模式四项写进技术要求，别只看 TDS 的初始值。",
  "imgKw": "胶接老化 湿热 紫外 增塑剂迁移 adhesion durability aging",
  "imgAi": "工程示意图：胶接接头在湿热、紫外、温度循环下的失效路径，以及由内聚破坏转为界面破坏的过程。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
