  "name": "静密封形式选型（垫片 / O 圈 / 密封胶 / 金属密封）",
  "lv": 1,
  "points": "按「压力 × 温度 × 介质 × 拆装频次」选：低压常温、平面大又不好做沟槽的用平面垫片（法兰、盖板）；中小尺寸、要中高压或真空的用 O 圈（沟槽加工最省，静密封可到 10MPa 以上，且有自紧效应）；既要密封又要固定的用密封胶（厌氧型填螺纹与刚性面，RTV 硅酮填缝但不承压）；高温高压、强腐蚀或要求金属对金属接触的用金属密封（金属垫圈、C 形环、锥面硬密封）。经验优先级：能上 O 圈就别用平面垫片——同样的密封效果下，O 圈沟槽体积小、可重复拆装、可靠性高一个量级。",
  "usage": "液压阀块盖板、减速箱端盖、泵壳、户外机柜、家电水箱、医疗器械外壳都用得到。选型顺序是先定压力与温度上限，再定形式，最后才谈材料——顺序反了会在材料上反复折腾而解决不了问题。",
  "imgKw": "静密封 形式 垫片 O形圈 金属密封 static seal gasket",
  "imgAi": "工程示意图：平面垫片、O 圈、密封胶与金属密封四种静密封形式的截面结构与适用压力温度区间。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
