  "name": "动密封选型（油封 / 唇形密封 / 格莱圈）",
  "lv": 1,
  "points": "按运动形式分家：旋转轴用唇形密封圈（油封，TC/TB 型），线速度一般 ≤10–15m/s、允许压力通常 ≤0.05MPa，压力更高要加副唇或改结构；往复或摆动（油缸、气缸活塞杆）用唇形密封（U/Y 形、V 形、斯特封），压力可达 16–40MPa；活塞与缸筒之间用格莱圈或斯特封（PTFE + O 圈组合），摩擦小、可承受较高压力但对间隙敏感。寿命由 PV 值（接触压力 × 滑动速度）与介质温度共同决定，PV 超限时摩擦热积累会烧唇口。设计要点是让唇口只受压不吃力——密封件必须被沟槽与挡圈限制住，不能让介质压力把它整体推出去。",
  "usage": "减速箱输入输出轴、电机轴、气动与液压缸、泵、电动工具、自动化设备的丝杆与导轨密封。询价前必须给出：轴径、转速、介质、压力、温度、偏心量与安装空间——缺一项供应商都会反问。",
  "imgKw": "动密封 油封 唇形密封 格莱圈 rotary shaft seal lip seal",
  "imgAi": "工程示意图：旋转轴油封、往复唇形密封与格莱圈（PTFE + O 圈）的截面结构与唇口受力方向。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
