  "name": "密封沟槽尺寸与公差",
  "lv": 2,
  "points": "沟槽有三个功能、对应三个尺寸：深度定压缩率（公差常取 ±0.03–0.05mm）、宽度给橡胶留变形空间（填充率 ≤85%，宽度公差 ±0.05–0.1mm）、槽口倒角做装配导入（R0.1–0.3 圆角加 15–30° 导入角），缺一项都会出问题。槽侧壁粗糙度 Ra 1.6–3.2μm 且必须无毛刺。往复动密封的沟槽要配挡圈槽，且沟槽与配合面的挤出间隙要按压力分级控制——间隙过大密封件会被挤入间隙切伤。采购标准 O 圈时沟槽必须按 GB/T 3452.3 或 ISO 3601-2 的对应尺寸，不要自创。",
  "usage": "O 圈、格莱圈、斯特封的沟槽图纸设计。设计顺序永远是「先选标准 O 圈，再按标准沟槽加工」；反过来自己定 O 圈尺寸，要开模、要定制刀具，成本和交期都上一个台阶。",
  "imgKw": "密封沟槽 尺寸 公差 倒角 填充率 O-ring groove",
  "imgAi": "工程示意图：O 圈沟槽的深度、宽度、槽底圆角与槽口导入角标注，附填充率与挤出间隙示意。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
