  "name": "密封失效排查（渗漏 / 冷凝 / 微漏）",
  "lv": 2,
  "points": "三类现象的原因树完全不同：① 渗漏（可见液体流出）——密封件挤出、切伤或老化（压缩永久变形）、沟槽超差、螺栓预紧不足或松弛、密封面损伤、压力超过设计值；② 冷凝（内部有水但外部没漏）——装配环境湿气被封入、材料放气、温差循环使水汽在冷表面析出、干燥剂饱和、呼吸通道缺失或被堵；③ 微漏（缓慢渗入或渗出、外观正常）——密封件与介质不相容（溶胀或收缩）、呼吸效应把水吸进来、密封面有贯穿性微观缺陷、装配时被毛刺或粉尘污染。排查顺序是先定现象、再定原因、最后验证：用荧光示踪、氦检或水检定位，再做拆解检查加尺寸复测加相容性核对加环境复现，不要在没定性前就换材料。",
  "usage": "客诉与可靠性验证阶段使用。建议做一张「现象→原因树→验证手段」三栏排查表，避免凭经验换料，也便于向客户交代整改依据（汽车与医疗客户通常要求 8D 报告）。",
  "imgKw": "密封失效 渗漏 冷凝 微漏 排查 leakage condensation troubleshooting",
  "imgAi": "工程示意图：渗漏、冷凝、微漏三类现象的原因树与对应验证手段（示踪、氦检、温度循环复现）。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
  "std": [
   "GB/T 4208-2017",
   "GB/T 2423.4-2008",
   "GB/T 2423.22-2012",
   "GB/T 10125-2021",
   "企标：密封失效排查与失效分析报告要求"
  ]
