  "name": "设计评审与阶段门评审",
  "lv": 2,
  "points": "有效的设计评审有三个硬条件：有清单（DFM、DFA、安规、成本、可装配逐项过）、有必须到场的人（结构、电子、工艺、品质、采购或 SQE，缺一方就有一类问题没人提）、有跟踪（每条问题有编号、责任人、关闭日期、验证方式）。评审会不是汇报会：汇报讲「我做了什么」，评审只讨论「哪里会出问题、凭什么说没问题」。评审的产出是一份带状态的问题清单，未关闭项超过 3 条不允许进下一阶段，允许带入的必须是「已改待验证」且由项目负责人签字背书。",
  "usage": "在方案定稿、3D 冻结、开模前、试产前、量产放行这五个时点各开一次；每次控制在 90–120 分钟，讨论对象是设计数据而不是幻灯片。",
  "imgKw": "设计评审 阶段评审 评审清单 问题清单 门径评审 design review",
  "imgAi": "工程示意图：设计评审的五类清单与问题闭环流程。线条简洁、轴侧视角、白底，关键部件引出标注，比例合理，无人物场景，工程师参考图风格。",
