  "name": "图纸发布与审核检查",
  "lv": 2,
  "points": "图纸发布前逐项过一张检查表：图框与标题栏（图号、名称、材料、版本、比例、投影法、签核齐全）、视图（投影法一致、剖视与局部视图清楚、不遗漏隐藏特征）、尺寸（关键尺寸带公差、未注公差在标题栏声明等级、形位公差有基准）、技术要求（材料牌号与标准号、表面处理、热处理、去毛刺倒角、清洁与包装）、版本与变更（首版或改版、变更处有云线标记）。签署链固定为设计→校对→审核→批准四级，缺一不可；批准后才能标 Released 并发放给供应商与检验。",
  "usage": "每张要开模、外协或作为检验依据的 2D 图都要过一遍；自用参考图与装配示意可简化，但只要图纸会被供应商或检验员拿在手上，就必须全项签核。",
