  "name": "试产到量产的移交",
  "lv": 2,
  "points": "试产（Pilot Run / PVT）的目的不是「做出来」，而是「用量产的人、量产的工装、量产的节拍做出来」，所以必须在量产线上由量产操作工完成。数量按件型定：注塑单件 300–1000 件、整机装配 50–200 台、汽车零部件按 PPAP 要求连续生产 300 件。放行条件要量化：装配直通率 ≥ 95%（消费电子）或 ≥ 98%（汽车、医疗），关键工序 Cpk ≥ 1.33，节拍不超过目标 CT 的 1.1 倍，治具检具完成移交并附校准证书，SOP 已发布并培训到岗。",
  "usage": "试产前一周锁定图纸与工艺并冻结 ECN 入口；试产当天设计、工艺、品质、供应商四方在场记录问题，通过后签「量产放行单」，此后任何改动都走 ECN。",
