  "name": "供应商技术交底与打样跟进",
  "lv": 2,
  "points": "技术交底会要讲清五件事：图纸与版本（哪一版是唯一依据）、关键尺寸与外观标准（附限度样板或色板）、材料与表面处理的验收判据、检验方式与抽样方案、交付节点及不合格的处理流程。责任划分必须在交底时写进协议：模具产权与保管责任、试模与改模费用归属（设计变更由采购方承担改模工时与材料，供应商做错自行返工）、图纸不得转用他方。打样跟进按里程碑走：T0 首试→全尺寸报告→外观确认→小批试装→承认书，每个节点都有明确的验收物，不能只看「样品收到了」。",
  "usage": "新供应商、新模具、新工艺第一次做件时必开；换料、换厂、改模后重开一次简版交底。供应商早期介入（ESI）越早越好，方案阶段就拉进来收益最大。",
