  "name": "设计问题闭环与经验沉淀",
  "lv": 3,
  "points": "问题清单（Issue Log）要能当台账用：每条含编号、发现阶段、现象、复现条件、影响（安全/功能/外观/成本/交期）、责任人、目标关闭日期、状态、根因、对策、验证方式。状态只允许前进不许跳跃：Open→处理中→已改待验证→Closed，只有验证通过才能关闭，改完没验证的一律挂在「已改待验证」。经验教训要写成可搜索的形式：场景 + 现象 + 判据数值 + 对策，标题里带上零件类型与失效现象，下次做类似件时能被搜到。",
  "usage": "每个项目结项时整理一次，按设计、工艺、材料、供应商、测试分类入库；新项目启动时先查库再设计，是最便宜的避坑手段。",
