  "name": "技术文件与说明书编制",
  "lv": 2,
  "points": "说明书要按「谁看、看什么、出问题怎么自救」来编：产品图示（爆炸图 + 零件编号）、规格参数、安装与使用步骤（图示优先、一步一图）、保养与清洁、故障排除表、安全警示（危险/警告/注意三级，带符号）、环保与回收标识、保修与售后信息。安全警示必须放在对应动作的同一位置（「清洁前必须断电」写在清洁步骤旁），集中放在最后一页等于没写，出事故时会被判未充分警示。出口产品要做多语言版本，并注意图示与符号优先于文字——能靠图说清的不要靠文字。",
  "usage": "所有带电、带运动件、带高温或压力的产品都要编制；医疗器械、儿童用品等还要满足各自的法规要求，说明书本身是受审文件的一部分。",
