  "lv": 2,
  "points": "数控转塔冲床用标准化刀具在平板上冲孔、步冲与成形：最小孔径约 1.0–1.3t 且 ≥1.2mm（铝可到 0.8t）；孔边距与外形不平行边 ≥t、平行边 ≥1.5t；可一体完成百叶窗、压线、压筋、翻边、沙拉孔与攻牙。异形孔靠小模步冲拼接，接刀处留接刀痕需去毛刺。",
  "usage": "网孔 / 群孔板、带成形特征（百叶窗 / 压线 / 翻边）的平板件首选；料厚超过 3mm 或不锈钢慎用（刀具磨损大）；折弯件与拉深件不能整体 NCT 下料。设计时避开夹钳死区（约 60–120mm 按模位），冲头直径不小于 2 倍料厚否则刀具寿命无保证。",
