  "lv": 2,
  "points": "下模 V 槽开口按料厚选：t≤3mm 取 V=6–8t、t>3mm 取 8–10t（V 越小内 R 越小、折弯力越大）；折弯力估算 F(吨/m)≈65×t²/V（σb=420MPa 口径；铝 ×0.65、不锈钢 ×1.6）。上模按形状选直刀 / 弯刀 / R 刀，88°/90° 刀口保角度稳定；内 R≈0.16V。",
  "usage": "出折弯件图前先核对 V 槽与最小直边（直边 >V/2），厚板与大边高件按吨位校核机台能力；铝板折弯开裂时增大 V 槽或加大上模 R；换 V 槽必须重算展开系数——同一套系数表脱离配套 V 槽就失效。",
  "imgKw": "折弯机 V槽 折弯模具 折弯力",
