  "lv": 2,
  "img": "images/plus53.jpg",
  "points": "凸包高度受拉伸极限约束：一步成形约 ≤6T，更高用两步法（先抽弧再整形）；压线宽 W≈T、深 ≈0.3t 用于引导折弯与减小凸包变形；止裂槽宽 >1.5T，工艺切口 S≥R、槽宽 k≥t、槽深 L≥t+R+k/2，防止折弯撕裂与毛边。",
  "usage": "百叶窗（a≥4t、b≥6t、h≤5t）、沙拉孔（90° 沉头 / 120° 拉铆）、死边（L≥3–3.5t+R）的限值出图时逐项核对；凸包距折弯线 <2.5t 时压平会压坏凸包，需套治具；打凸间距与到边距离按 D 分档控制。",
