  "lv": 2,
  "points": "冲裁 / 切割毛刺不可避免，只能控制与清除：毛刺高经验值按料厚 0.05–0.35mm 分档；验收按表面处理类型分档——喷涂件可不除均匀毛刺、电镀件 45° 触摸不刮手、不处理件全部清除。毛刺方向朝凸模出口，出图必须标注朝向。",
  "usage": "图纸技术要求写明毛刺面朝向（一般朝内、非配合面）；激光与 NCT 件报价计入去毛刺工时（数冲去毛刺时间 ≈ 冲切时间 ×2）；电镀与拉丝件毛刺要求最严需单独打磨；点焊搭接面毛刺会造成虚焊。",
