  "lv": 2,
  "img": "images/plus56.jpg",
  "points": "报价模型 = 材料费 + 加工费 + 表面处理费 + 外购件 + 装配包装 + 管理利润税费；材料费按展开重量 × 损耗系数（常规 1.15）；加工费按工序单价——激光 / NCT 按米或台时、折弯按刀、焊接按点 / 厘米、喷涂按 ㎡。批量决定单价档位，打样系数 3–5 倍。",
  "usage": "结构工程师自检成本：减刀数与焊缝长度、合并孔位、控制展开利用率是设计端三大降本杠杆；外协比价按同一工序拆分口径核对；谈清含税口径与小件最低收费（喷涂 / 折弯开机费）；模具费 3 个月内摊完为合理。",
